      "content": "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Starfall</title>\n<style>\n  html, body { margin: 0; height: 100%; background: #0d1020; overflow: hidden; }\n  canvas { display: block; width: 100vw; height: 100vh; touch-action: none; }\n</style>\n</head>\n<body>\n<canvas id=\"game\" aria-label=\"Starfall: move the basket to catch falling stars\"></canvas>\n<script>\n// A tiny game used to test the visual-check skill: catch falling stars with a basket.\n// window.__myrelTest is the test hook the skill drives: seed(n) restarts it with fixed randomness\n// and stops the real-time loop, step(ms) advances the simulation, state() reports it.\n// ?bug=frozen draws once and never again, which the frame check must catch.\nconst canvas = document.getElementById(\"game\");\nconst g = canvas.getContext(\"2d\");\nconst bug = new URLSearchParams(location.search).get(\"bug\");\nlet W = 0, H = 0, rng = Math.random, manual = false;\nconst game = { phase: \"play\", score: 0, lives: 3, stars: [], basket: 0.5, spawn: 0, t: 0 };\n\nfunction mulberry32(a) {\n  return () => { a |= 0; a = (a + 0x6d2b79f5) | 0; let t = Math.imul(a ^ (a >>> 15), 1 | a); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };\n}\nfunction resize() {\n  const dpr = window.devicePixelRatio || 1;\n  W = canvas.clientWidth; H = canvas.clientHeight;\n  canvas.width = Math.round(W * dpr); canvas.height = Math.round(H * dpr);\n  g.setTransform(dpr, 0, 0, dpr, 0, 0);\n}\nfunction reset() { Object.assign(game, { phase: \"play\", score: 0, lives: 3, stars: [], basket: 0.5, spawn: 0, t: 0 }); }\nfunction update(dt) {\n  if (game.phase !== \"play\") return;\n  game.t += dt;\n  game.spawn -= dt;\n  if (game.spawn <= 0) { game.stars.push({ x: 0.08 + rng() * 0.84, y: -0.05, v: 0.18 + rng() * 0.12, r: 6 + rng() * 6 }); game.spawn = 0.6; }\n  // The basket drifts toward the lowest star so the game plays itself under test.\n  const target = game.stars.reduce((a, s) => (s.y > (a?.y ?? -1) ? s : a), null);\n  if (target) game.basket += Math.sign(target.x - game.basket) * Math.min(Math.abs(target.x - game.basket), dt * 0.5);\n  for (const s of game.stars) s.y += s.v * dt;\n  const bw = Math.max(70, W * 0.16) / W;\n  game.stars = game.stars.filter((s) => {\n    if (s.y > 0.9 && s.y < 0.95 && Math.abs(s.x - game.basket) < bw / 2) { game.score += 10; return false; }\n    if (s.y > 1.05) { game.lives -= 1; return false; }\n    return true;\n  });\n  if (game.lives <= 0) game.phase = \"over\";\n}\nfunction star(x, y, r) {\n  g.beginPath();\n  for (let i = 0; i < 10; i++) { const a = (i * Math.PI) / 5 - Math.PI / 2, d = i % 2 ? r * 0.45 : r; g.lineTo(x + Math.cos(a) * d, y + Math.sin(a) * d); }\n  g.closePath(); g.fill();\n}\nfunction draw() {\n  const sky = g.createLinearGradient(0, 0, 0, H);\n  sky.addColorStop(0, \"#0d1020\"); sky.addColorStop(1, \"#27204a\");\n  g.fillStyle = sky; g.fillRect(0, 0, W, H);\n  g.fillStyle = \"#ffd76a\";\n  for (const s of game.stars) star(s.x * W, s.y * H, s.r);\n  const bw = Math.max(70, W * 0.16);\n  g.fillStyle = \"#6ee7c8\";\n  g.fillRect(game.basket * W - bw / 2, H * 0.92, bw, 14);\n  g.fillStyle = \"#f2f4ff\";\n  g.font = \"600 20px system-ui, sans-serif\";\n  g.textBaseline = \"top\";\n  g.fillText(`Score ${game.score}`, 16, 16);\n  g.textAlign = \"right\";\n  g.fillText(\"♥\".repeat(Math.max(0, game.lives)), W - 16, 16);\n  g.textAlign = \"left\";\n  if (game.phase === \"over\") {\n    g.fillStyle = \"rgba(0,0,0,0.6)\"; g.fillRect(0, 0, W, H);\n    g.fillStyle = \"#ffffff\"; g.font = \"700 36px system-ui, sans-serif\"; g.textAlign = \"center\";\n    g.fillText(\"Game over\", W / 2, H / 2 - 20); g.textAlign = \"left\";\n  }\n}\nlet last = performance.now();\nfunction loop(now) {\n  if (!manual) { update(Math.min(0.05, (now - last) / 1000)); draw(); }\n  last = now;\n  if (bug !== \"frozen\") requestAnimationFrame(loop);\n}\nwindow.addEventListener(\"resize\", () => { resize(); draw(); });\nwindow.addEventListener(\"pointermove\", (e) => { game.basket = e.clientX / W; });\nresize(); draw();\nrequestAnimationFrame(loop);\n\nwindow.__myrelTest = {\n  ready: () => W > 0,\n  seed(n) { rng = mulberry32(n); manual = true; reset(); draw(); },\n  step(ms) { if (bug === \"frozen\") return; for (let t = 0; t < ms; t += 16) update(0.016); draw(); },\n  state: () => ({ phase: game.phase, score: game.score, lives: game.lives, stars: game.stars.length }),\n};\n</script>\n</body>\n</html>\n"
